export function translatePage(lang){const dictionary=messages[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-i18n]').forEach(el=>{const value=dictionary[el.dataset.i18n];if(value!==undefined){el.textContent=value;el.style.whiteSpace='pre-line';}});document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang));});document.querySelector('#main-nav')?.setAttribute('aria-label',dictionary.navLabel);document.querySelector('.match-tabs')?.setAttribute('aria-label',dictionary.filterLabel);document.querySelector('.sizes')?.setAttribute('aria-label',dictionary.sizeGroup);document.querySelector('.brand')?.setAttribute('aria-label',dictionary.homeLabel);document.querySelector('.language')?.setAttribute('aria-label',dictionary.langLabel);document.querySelectorAll('.close-dialog').forEach(b=>b.setAttribute('aria-label',dictionary.close));document.getElementById('cart-trigger').setAttribute('aria-label',dictionary.cartLabel);document.getElementById('reset-view')?.setAttribute('aria-label',dictionary.resetView);if(document.getElementById('shirt-name'))document.getElementById('shirt-name').placeholder=dictionary.namePlaceholder;document.querySelector('#jersey-mount canvas')?.setAttribute('aria-label',dictionary.canvasLabel);document.title=lang==='ar'?'ديما ماص — شغف تتوارثه الأجيال':'DIMA MAS — La passion en héritage';}
